import React from 'react';
import ReactDOM from 'react-dom/client';
import './index.css';
import App from './App';

const root = ReactDOM.createRoot(
  document.getElementById('root') as HTMLElement
);

const app = (
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

root.render(process.env.NODE_ENV === 'production' ? app : <App />);
